}

function runtimeBridge(initialSnapshot: ClaudeRateLimitSnapshot | null) {
    let listener: ((value: ClaudeRateLimitSnapshot) => void) | null = null
    const bridge: ElectronClaudeRuntimeBridge = {
        getClaudeRateLimits: vi.fn(async () => initialSnapshot),
        onClaudeRateLimits: vi.fn((callback) => {
            listener = callback

            return vi.fn()
        }),
    }

    return { bridge, emit: (value: ClaudeRateLimitSnapshot) => listener?.(value) }
}

async function renderStatus(initialSnapshot: ClaudeRateLimitSnapshot | null, mobile = false) {
    const runtime = runtimeBridge(initialSnapshot)
    setClaudeRuntimeBridgeOverride(runtime.bridge)
    claudeRateLimitService.start()
    render(<ClaudeRateLimitStatus mobile={mobile} />)
    await act(async () => {
        await Promise.resolve()
    })

    return runtime
}

describe('ClaudeRateLimitStatus', () => {

    private handleConnectionChange(bridge: ElectronClaudeRuntimeBridge, connected: boolean) {
        if (bridge !== this.bridge) return
        if (!connected) {
            this.markStale()
            return
        }

        void this.refresh(bridge)
    }

    private scheduleExpiration(snapshot: ClaudeRateLimitSnapshot, receivedAt: number) {
        if (this.expirationTimer) clearTimeout(this.expirationTimer)
        this.expirationTimer = null
        if (!snapshot.available) return
        const resetTime = firstResetTime(snapshot)
        if (resetTime === null) return
        const localResetTime = receivedAt + resetTime - snapshot.observedAt
        const delay = Math.max(0, localResetTime - Date.now())
        if (delay === 0) {
            this.markStale()
            return
        }
        this.expirationTimer = setTimeout(() => this.markStale(), delay)
    }

    private markStale() {
        if (!this.state.snapshot || this.state.stale) return

        this.setState({ ...this.state, stale: true })
    }

    private unsubscribe() {
        this.unsubscribeRateLimits?.()
        this.unsubscribeConnection?.()
        this.unsubscribeRateLimits = null
        this.unsubscribeConnection = null
